&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;I&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;ntegrated Design &amp;amp; Creative Production&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Concept and create on-brand integrated work across the full channel mix, brand campaigns, digital and social content, motion, print, events,&amp;nbsp;marketing collateral,&amp;nbsp;thought leadership, and long-form communications, from brief through to final delivery&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
